/bin/bash -lc "node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const dir = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '0', DB_PATH: join(dir, 'db.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Startup timeout')), 5000);
    child.stdout.on('data', chunk => {
      const match = String(chunk).match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start and GET /health passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(dir, { recursive: true, force: true });
}
EOF
git diff --check
git add server.js styles.css README.md test/due-range.test.js
git commit -m \"Add inclusive due-date range filtering while preserving selected filters\"
git status --porcelain
git rev-parse HEAD"

